{
  "axes": [
    {
      "axis_id":  "本体形状（断面・立体的輪郭）",
      "label_ja": "本体の幾何形状",
      "values": ["円柱型", "角柱型（四角／八角など）", "先端が細くなる錐型", "扁平・板状", "基部が広がるスカート型", "不規則・曲線主体", "その他"]
    ,
    "why_ja": "外形の輪郭を捉える軸です。表面の仕上げや塗色とは独立しています。"
    },
    {
      "axis_id": "surface_finish",
      "label_ja": "表面の質感・材質感",
      "values": ["金属光沢（亜鉛メッキ・鋼など）", "塗装面（つや消し）", "塗装面（つやあり）", "プラスチック・合成樹脂質感", "コンクリート風", "木目調", "表面にリブ・段差・凹凸有", "その他"]
    ,
      "why_ja": "材質由来の視覚的質感を分類します。形状や塗色とは無相関です。"
    },
    {
      "axis_id": "mark_layout",
      "label_ja": "視認マークの配置パターン",
      "values": ["無柄", "水平帯1本", "水平帯複数（等間隔）", "縦帯", "斜め帯（矢印／コーン状）", "全体覆い型", "キャップ部のみ帯", "その他"]
    ,
      "why_ja": "マークの「形状と配置方向」を扱います。色違いは本軸では区別しません。"
    },
    {
      "axis_id": "top_design",
      "label_ja": "頭部（トップ）の造形",
      "values": ["平面", "丸み", "尖り・切欠き", "反射板キャップ一体", "突起・取付部有", "光導管／LED埋め込み風", "フラッシュマウント風", "その他"]
    ,
      "why_ja": "頂部の構造・形状を独立して捉えます。本体形状や帯配置とは無関係です。"
    },
    {
      "axis_id": "base_structure",
      "label_ja": "基部（フット）の構造形態",
      "values": ["地面直打埋設", "拡底座（スカート）", "固定ボルト／プレート露出", "床面フラッシュ", "装飾台座", "接合部が段差付き", "その他"]
    ,
      "why_ja": "設置構造に由来する視覚的特徴を扱います。本体形状や色とは独立しています。"
    },
    {
      "axis_id": "color_composition",
      "label_ja": "色彩構成（色合いとコントラストの関係）",
      "values": ["単色塗り", "2色帯（白×赤）", "2色帯（白×黄）", "2色帯（白×黒）", "2色帯（白×青）", "3色以上帯", "対照色組み合わせ", "同系色グラデーション", "無彩色ベース", "その他"]
    ,
      "why_ja": "色の「組み合わせ方とコントラスト強度」を扱います。帯の配置方向は本軸では区別しません。"
    }
  ]
}
